/**
 * `coverage`: board × class × subject × asset-type counts against the targets in CONTEXT §4/§10
 * and content-targets.ts. This report is a launch gate (ARCHITECTURE §8.2, AGENTS §7).
 *
 * Counted from pipeline output in out/ (M1); M2 switches the source to published releases in
 * Postgres. A chapter counts for an asset only when the asset meets its target and the unit's
 * last lint had zero errors: deck (all parts), notes, flashcards (20–40), practice (≥ 60/40).
 * Chapter tests and test series are assembled in M2 (stage 7) and count 0 until then.
 * Units generated by the mock provider (provenance model "mock") are placeholder text and never count.
 */
import fs from 'node:fs';
import path from 'node:path';
import { CONTENT_TARGETS, TEST_SERIES_TARGETS } from '@soyl/shared/config/content-targets';
import type { Subject } from '@soyl/shared/content/index';
import { subjectsInScope, type Scope } from '../catalog';
import { readJsonIf, table, writeJson } from '../io';
import { unitOutDir } from '../paths';
import type { Pipeline } from '../pipeline';

export const ASSETS = ['deck', 'notes', 'flashcards', 'practice', 'chapter_tests'] as const;
type Asset = (typeof ASSETS)[number];

export interface SubjectCoverage {
  subject: string;
  board: string;
  exam: string;
  class: number;
  name: string;
  tier: string;
  wave: number;
  syllabus: boolean;
  chapters: number;
  /** Chapters whose output is mock placeholder content (never counted). */
  mock_units: number;
  /** Chapters meeting each asset target (chapter_tests counts tests, target 2 per chapter). */
  have: Record<Asset, number>;
  target: Record<Asset, number>;
  series: { have: Record<string, number>; target: Record<string, number> };
  complete: boolean;
}

export interface CoverageReport {
  generated_at: string;
  source: string;
  scope: Scope;
  subjects: SubjectCoverage[];
  totals: { subjects: number; with_syllabus: number; chapters: number; mock_units: number; have: Record<Asset, number>; target: Record<Asset, number>; complete_subjects: number };
  gate: 'PASS' | 'FAIL';
}

function seriesTargets(s: Subject): Record<string, number> {
  if ((TEST_SERIES_TARGETS.boardClasses.classes as readonly number[]).includes(s.class)) {
    const t: Record<string, number> = {
      unit_tests: TEST_SERIES_TARGETS.boardClasses.unitTests,
      full_mocks: TEST_SERIES_TARGETS.boardClasses.fullMocksMin,
      live_mocks: TEST_SERIES_TARGETS.boardClasses.liveMocks,
    };
    if (s.board === 'cbse' && s.class === 10 && s.has_board_exam) t.second_exam_track = 1;
    return t;
  }
  return { unit_tests: TEST_SERIES_TARGETS.otherClasses.unitTestsMin, term_papers: TEST_SERIES_TARGETS.otherClasses.termPapersMin };
}

function isMock(dir: string): boolean {
  const prov = (f: string) => readJsonIf<{ provenance?: { model?: string } }>(path.join(dir, f))?.provenance?.model;
  return prov('notes.json') === 'mock' || prov('flashcards.json') === 'mock' || prov('outline.json') === 'mock';
}

function unitHas(dir: string, classLevel: number): Record<Asset, number> & { mock: number } {
  const has = { deck: 0, notes: 0, flashcards: 0, practice: 0, chapter_tests: 0, mock: 0 };
  if (!fs.existsSync(dir)) return has;
  if (isMock(dir)) return { ...has, mock: 1 };
  const lint = readJsonIf<{ errors: number }>(path.join(dir, 'lint.json'));
  if (!lint || lint.errors > 0) return has;
  if (fs.readdirSync(dir).some((f) => /^deck\.p\d+\.json$/.test(f))) has.deck = 1;
  if (fs.existsSync(path.join(dir, 'notes.json'))) has.notes = 1;
  const cards = readJsonIf<{ cards: unknown[] }>(path.join(dir, 'flashcards.json'))?.cards.length ?? 0;
  if (cards >= CONTENT_TARGETS.flashcardsMin && cards <= CONTENT_TARGETS.flashcardsMax) has.flashcards = 1;
  const qs = readJsonIf<{ questions: unknown[] }>(path.join(dir, 'questions.json'))?.questions.length ?? 0;
  if (qs >= (CONTENT_TARGETS.practiceQuestionsMin[classLevel] ?? 40)) has.practice = 1;
  return has;
}

export function coverageReport(p: Pipeline, scope: Scope): CoverageReport {
  const subjects: SubjectCoverage[] = subjectsInScope(p.catalog, scope).map((s) => {
    const syl = p.catalog.syllabi.get(s.id);
    const chapters = syl?.chapters.length ?? 0;
    const have: Record<Asset, number> = { deck: 0, notes: 0, flashcards: 0, practice: 0, chapter_tests: 0 };
    let mock_units = 0;
    for (const ch of syl?.chapters ?? []) {
      const h = unitHas(unitOutDir(p.paths.outDir, ch.id), s.class);
      for (const a of ASSETS) have[a] += h[a];
      mock_units += h.mock;
    }
    const target: Record<Asset, number> = { deck: chapters, notes: chapters, flashcards: chapters, practice: chapters, chapter_tests: chapters * CONTENT_TARGETS.chapterTests };
    const st = seriesTargets(s);
    const series = { have: Object.fromEntries(Object.keys(st).map((k) => [k, 0])), target: st };
    const complete = !!syl && chapters > 0 && ASSETS.every((a) => have[a] >= target[a]) && Object.keys(st).every((k) => series.have[k]! >= st[k]!);
    return { subject: s.id, board: s.board, exam: s.exam, class: s.class, name: s.name, tier: s.tier, wave: s.wave, syllabus: !!syl, chapters, mock_units, have, target, series, complete };
  });
  const sum = (f: (s: SubjectCoverage) => number) => subjects.reduce((n, s) => n + f(s), 0);
  const totals = {
    subjects: subjects.length,
    with_syllabus: subjects.filter((s) => s.syllabus).length,
    chapters: sum((s) => s.chapters),
    have: Object.fromEntries(ASSETS.map((a) => [a, sum((s) => s.have[a])])) as Record<Asset, number>,
    target: Object.fromEntries(ASSETS.map((a) => [a, sum((s) => s.target[a])])) as Record<Asset, number>,
    complete_subjects: subjects.filter((s) => s.complete).length,
    mock_units: sum((s) => s.mock_units),
  };
  return {
    generated_at: new Date().toISOString(),
    source: `pipeline output (${p.paths.outDir}); lint-clean units only`,
    scope,
    subjects,
    totals,
    gate: subjects.length > 0 && subjects.every((s) => s.complete) ? 'PASS' : 'FAIL',
  };
}

const frac = (have: number, target: number) => `${have}/${target}`;

export function coverageMarkdown(r: CoverageReport): string {
  const lines = [
    '# Content coverage',
    '',
    `Generated ${r.generated_at}. Source: ${r.source}. Gate: **${r.gate}** (${r.totals.complete_subjects}/${r.totals.subjects} subjects complete).`,
    '',
    'A subject is complete when every chapter has a lint-clean deck, notes, 20–40 flashcards, the practice minimum, 2 chapter tests, and the subject has its test series (CONTEXT §4, §10). Chapter tests and series are assembled in M2.',
    '',
    '| Subject | Wave | Syllabus | Chapters | Deck | Notes | Flashcards | Practice | Chapter tests | Test series | Complete |',
    '|---|---|---|---|---|---|---|---|---|---|---|',
    ...r.subjects.map(
      (s) =>
        `| ${s.subject} | ${s.wave} | ${s.syllabus ? 'yes' : '**no**'} | ${s.chapters} | ${frac(s.have.deck, s.target.deck)} | ${frac(s.have.notes, s.target.notes)} | ${frac(s.have.flashcards, s.target.flashcards)} | ${frac(s.have.practice, s.target.practice)} | ${frac(s.have.chapter_tests, s.target.chapter_tests)} | ${Object.keys(s.series.target).map((k) => `${k} ${s.series.have[k]}/${s.series.target[k]}`).join(', ')} | ${s.complete ? 'yes' : 'no'} |`,
    ),
  ];
  return `${lines.join('\n')}\n`;
}

export function coverageCommand(p: Pipeline, scope: Scope, opts: { out?: string; gate?: boolean; detail?: boolean } = {}): { report: CoverageReport; files: string[]; exitCode: number } {
  const r = coverageReport(p, scope);
  const detail = opts.detail ?? !!(scope.subject || scope.class !== undefined);
  if (detail) {
    p.log(
      table(
        ['subject', 'wave', 'chapters', 'deck', 'notes', 'flashcards', 'practice', 'ch.tests', 'series', 'complete'],
        r.subjects.map((s) => [
          s.subject,
          s.wave,
          s.syllabus ? s.chapters : 'no syllabus',
          frac(s.have.deck, s.target.deck),
          frac(s.have.notes, s.target.notes),
          frac(s.have.flashcards, s.target.flashcards),
          frac(s.have.practice, s.target.practice),
          frac(s.have.chapter_tests, s.target.chapter_tests),
          Object.keys(s.series.target).map((k) => `${s.series.have[k]}/${s.series.target[k]}`).join(' '),
          s.complete ? 'yes' : 'no',
        ]),
        ['l', 'r', 'r', 'r', 'r', 'r', 'r', 'r', 'l', 'l'],
      ),
    );
  } else {
    const groups = new Map<string, SubjectCoverage[]>();
    for (const s of r.subjects) groups.set(`${s.board}|${s.exam}|${s.class}`, [...(groups.get(`${s.board}|${s.exam}|${s.class}`) ?? []), s]);
    const rows = [...groups.entries()]
      .sort(([a], [b]) => a.split('|')[0]!.localeCompare(b.split('|')[0]!) || Number(a.split('|')[2]) - Number(b.split('|')[2]) || a.localeCompare(b))
      .map(([key, list]) => {
        const sum = (f: (s: SubjectCoverage) => number) => list.reduce((n, s) => n + f(s), 0);
        return [
          ...key.split('|'),
          list.length,
          list.filter((s) => s.syllabus).length,
          sum((s) => s.chapters),
          ...ASSETS.map((a) => frac(sum((s) => s.have[a]), sum((s) => s.target[a]))),
          list.filter((s) => s.complete).length,
        ];
      });
    p.log(table(['board', 'exam', 'class', 'subjects', 'syllabi', 'chapters', 'deck', 'notes', 'flashcards', 'practice', 'ch.tests', 'complete'], rows, ['l', 'l', 'r', 'r', 'r', 'r', 'r', 'r', 'r', 'r', 'r', 'r']));
  }
  const t = r.totals;
  p.log(`total: ${t.subjects} subjects (${t.with_syllabus} with syllabus), ${t.chapters} chapters; ${ASSETS.map((a) => `${a} ${frac(t.have[a], t.target[a])}`).join(', ')}`);
  if (t.mock_units) p.log(`${t.mock_units} unit(s) in out/ hold mock placeholder content and are not counted`);
  p.log(`coverage gate: ${r.gate} (${t.complete_subjects}/${t.subjects} subjects complete)`);
  const base = opts.out ?? path.join(p.paths.outDir, 'coverage', 'coverage');
  const files = [`${base}.json`, `${base}.md`];
  writeJson(files[0]!, r);
  fs.writeFileSync(files[1]!, coverageMarkdown(r));
  p.log(`wrote ${files.join(' and ')}`);
  return { report: r, files, exitCode: opts.gate && r.gate !== 'PASS' ? 1 : 0 };
}
